      }
    }
  }

  private getPenaltyScore(): number {
    let result = 0;
    const size = this.size;
    // Adjacent runs in rows/cols
    for (let y = 0; y < size; y++) {
      let runColor = false, runX = 0;
      const runHistory = [0, 0, 0, 0, 0, 0, 0];
      for (let x = 0; x < size; x++) {
        if (this.modules[y][x] === runColor) {
          runX++;
          if (runX === 5) result += 3;
          else if (runX > 5) result++;
        } else {
          this.finderPenaltyAddHistory(runX, runHistory);
          if (!runColor) result += this.finderPenaltyCountPatterns(runHistory) * 40;
          runColor = this.modules[y][x];
          runX = 1;
        }
      }
      result += this.finderPenaltyTerminateAndCount(runColor, runX, runHistory) * 40;
    }
    for (let x = 0; x < size; x++) {
      let runColor = false, runY = 0;
      const runHistory = [0, 0, 0, 0, 0, 0, 0];
      for (let y = 0; y < size; y++) {
        if (this.modules[y][x] === runColor) {
          runY++;
          if (runY === 5) result += 3;
          else if (runY > 5) result++;
        } else {
          this.finderPenaltyAddHistory(runY, runHistory);
          if (!runColor) result += this.finderPenaltyCountPatterns(runHistory) * 40;
          runColor = this.modules[y][x];
          runY = 1;
        }
      }
      result += this.finderPenaltyTerminateAndCount(runColor, runY, runHistory) * 40;
    }
    // 2x2 blocks
    for (let y = 0; y < size - 1; y++) {
      for (let x = 0; x < size - 1; x++) {
        const c = this.modules[y][x];
        if (c === this.modules[y][x + 1] && c === this.modules[y + 1][x] && c === this.modules[y + 1][x + 1]) result += 3;
      }
    }
    // Balance of dark modules
    let dark = 0;
    for (const row of this.modules) for (const cell of row) if (cell) dark++;
    const total = size * size;
    const k = Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1;
    result += k * 10;
    return result;
  }

  private finderPenaltyCountPatterns(rh: number[]): number {
    const n = rh[1];
    const core = n > 0 && rh[2] === n && rh[3] === n * 3 && rh[4] === n && rh[5] === n;
    return (core && rh[0] >= n * 4 && rh[6] >= n ? 1 : 0) + (core && rh[6] >= n * 4 && rh[0] >= n ? 1 : 0);
  }

  private finderPenaltyTerminateAndCount(currentColor: boolean, currentRun: number, rh: number[]): number {
    if (currentColor) {
      this.finderPenaltyAddHistory(currentRun, rh);
      currentRun = 0;
    }
    currentRun += this.size;
    this.finderPenaltyAddHistory(currentRun, rh);
    return this.finderPenaltyCountPatterns(rh);
  }

  private finderPenaltyAddHistory(currentRun: number, rh: number[]): void {
    if (rh[0] === 0) currentRun += this.size;
    rh.pop();
    rh.unshift(currentRun);
  }
}

function encodeBytes(data: number[]): QrMatrix {
  // Build the byte-mode bit stream, choose the smallest version that fits.
  const ecl = ECC.MEDIUM;
  let version = MIN_VERSION;
  let dataCapacityBits = 0;
  for (; ; version++) {
    if (version > MAX_VERSION) throw new Error("Data too long for a QR code");
    dataCapacityBits = getNumDataCodewords(version, ecl) * 8;
    const ccbits = version <= 9 ? 8 : 16;
    const usedBits = 4 + ccbits + data.length * 8;
    if (usedBits <= dataCapacityBits) break;
  }

  const bb: number[] = [];
  appendBits(0x4, 4, bb); // byte mode indicator
  appendBits(data.length, version <= 9 ? 8 : 16, bb);
  for (const b of data) appendBits(b, 8, bb);

  // Terminator + bit/byte padding
  appendBits(0, Math.min(4, dataCapacityBits - bb.length), bb);
  appendBits(0, (8 - (bb.length % 8)) % 8, bb);
  for (let padByte = 0xec; bb.length < dataCapacityBits; padByte ^= 0xec ^ 0x11) appendBits(padByte, 8, bb);

  const dataCodewords: number[] = new Array(bb.length >>> 3).fill(0);
  bb.forEach((bit, i) => (dataCodewords[i >>> 3] |= bit << (7 - (i & 7))));

  return new QrMatrix(version, ecl, dataCodewords, -1);
}

/**
 * Encode `text` (UTF-8) as a QR code and return a standalone <svg> string.
 * `border` is the quiet-zone width in modules; `size` is the CSS pixel size.
 */
export function qrSvg(text: string, opts: { size?: number; border?: number; className?: string } = {}): string {
  const border = opts.border ?? 3;
  const px = opts.size ?? 220;
  const bytes = Array.from(new TextEncoder().encode(text));
  const qr = encodeBytes(bytes);
  const dim = qr.size + border * 2;

  let path = "";
  for (let y = 0; y < qr.size; y++) {
    for (let x = 0; x < qr.size; x++) {
      if (qr.getModule(x, y)) path += `M${x + border},${y + border}h1v1h-1z`;
    }
  }
  const cls = opts.className ? ` class="${opts.className}"` : "";
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${dim} ${dim}" ` +
    `width="${px}" height="${px}" shape-rendering="crispEdges"${cls} role="img" aria-label="QR code">` +
    `<rect width="${dim}" height="${dim}" fill="#ffffff"/>` +
    `<path d="${path}" fill="#000000"/>` +
    `</svg>`
  );
}

import { randomInt } from "crypto";
import type { Prisma, PrismaClient } from "@prisma/client";

// ── Gift cards ────────────────────────────────────────────────────────────────
// A gift card is a bearer instrument scoped to one tenant. `balance` is the
// single source of truth; every movement is mirrored in a GiftCardTxn ledger
// row so the running total is always auditable and reconstructable. Redemption
// draws the balance down atomically (never below zero, never twice for the same
// spend) — see redeemGiftCard.

export const GIFT_CARD_MIN = 5; // smallest sellable amount, in the studio's currency
export const GIFT_CARD_MAX = 2000; // cap to keep a single Stripe charge sane
export const GIFT_CARD_VALIDITY_DAYS = 365; // cards expire a year after purchase

// Unambiguous alphabet — no 0/O/1/I/L so a code is easy to read aloud/type.
const CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";

function randomBlock(len: number): string {
  let out = "";
  for (let i = 0; i < len; i++) out += CODE_ALPHABET[randomInt(CODE_ALPHABET.length)];
  return out;
}

/** Human-friendly code like `GIFT-4KPA-7Z3M-QF9T`. */
export function generateGiftCardCode(): string {
  return `GIFT-${randomBlock(4)}-${randomBlock(4)}-${randomBlock(4)}`;
}

/** Normalise user input (paste, spaces, lowercase) to the canonical form. */
export function normaliseCode(raw: string): string {
  return raw.trim().toUpperCase().replace(/\s+/g, "").replace(/[^A-Z0-9-]/g, "");
}

// db can be the PrismaClient or an interactive-transaction client.
type Db = PrismaClient | Prisma.TransactionClient;

/**
 * Allocate a code that is unique within the tenant. Retries on the (rare)
 * collision; the caller still relies on the DB unique index as the final guard.
 */
export async function allocateUniqueCode(db: Db, tenantId: string): Promise<string> {
  for (let i = 0; i < 6; i++) {
    const code = generateGiftCardCode();
    const clash = await db.giftCard.findFirst({ where: { tenantId, code }, select: { id: true } });
    if (!clash) return code;
  }
  // Fall back to a longer code — collision odds are astronomically low.
  return `GIFT-${randomBlock(4)}-${randomBlock(4)}-${randomBlock(4)}-${randomBlock(4)}`;
}

export type RedeemResult =
  | { ok: true; applied: number; balanceAfter: number; giftCardId: string; code: string }
  | { ok: false; reason: "not_found" | "inactive" | "expired" | "empty" };

/**
 * Draw `requested` off a gift card, atomically, inside an existing
 * transaction. Partial redemption is supported: we apply min(requested,
 * balance) and return how much was actually applied.
 *
 * Double-spend / race safety: the decrement is a conditional updateMany with
 * `balance >= applied` in the WHERE clause. Postgres takes a row lock for the
 * UPDATE, so two concurrent redemptions serialise; the second one re-reads the
 * now-lower balance (via the guard) and can never drive the balance negative
 * or apply more than exists. If the guarded update touches 0 rows we abort.
 */
export async function redeemGiftCard(
  tx: Prisma.TransactionClient,
  args: { tenantId: string; code: string; requested: number; bookingId?: string | null; note?: string },
): Promise<RedeemResult> {
  const code = normaliseCode(args.code);
  const card = await tx.giftCard.findFirst({ where: { tenantId: args.tenantId, code } });
  if (!card) return { ok: false, reason: "not_found" };
  if (card.status !== "ACTIVE") return { ok: false, reason: "inactive" };
  if (card.expiresAt && card.expiresAt.getTime() < Date.now()) {
    await tx.giftCard.update({ where: { id: card.id }, data: { status: "EXPIRED" } });
    return { ok: false, reason: "expired" };
  }

  const balance = Number(card.balance);
  if (balance <= 0) return { ok: false, reason: "empty" };

  const applied = Math.min(Math.max(0, args.requested), balance);
  if (applied <= 0) return { ok: false, reason: "empty" };

  // Guarded, atomic decrement — only succeeds while the balance still covers it.
  const updated = await tx.giftCard.updateMany({
    where: { id: card.id, status: "ACTIVE", balance: { gte: applied.toFixed(2) } },
    data: { balance: { decrement: applied.toFixed(2) } },
  });
  if (updated.count !== 1) {
    // Lost the race — someone else spent it first. Caller should retry/refuse.
    return { ok: false, reason: "empty" };
  }

  const balanceAfter = Number((balance - applied).toFixed(2));
  await tx.giftCardTxn.create({
    data: {
      giftCardId: card.id,
      amount: (-applied).toFixed(2),
      type: "REDEEM",
      bookingId: args.bookingId ?? null,
      note: args.note ?? null,
    },
  });
  // Fully-spent cards flip to REDEEMED so they drop out of "active" lists.
  if (balanceAfter <= 0) {
    await tx.giftCard.update({ where: { id: card.id }, data: { status: "REDEEMED" } });
  }

  return { ok: true, applied, balanceAfter, giftCardId: card.id, code };
}

/** Plain-text purchase email (the mailer sends text/plain only). */
export function purchaseEmailBody(args: {
  studio: string;
  amount: string; // pre-formatted with currency
  code: string;
  message?: string | null;
  viewUrl?: string;
}): { subject: string; body: string } {
  const lines = [
    `You've received a ${args.studio} gift card!`,
    "",
    `Amount: ${args.amount}`,
    `Gift code: ${args.code}`,
  ];
  if (args.message) lines.push("", `Message: "${args.message}"`);
  if (args.viewUrl) lines.push("", `View & redeem your gift card: ${args.viewUrl}`);
  lines.push(
    "",
    "Present this code (or the QR on the link above) at the studio, or enter it at",
    "checkout to draw down the balance. Enjoy!",
    "",
    `— ${args.studio}`,
  );
  return { subject: `Your ${args.studio} gift card`, body: lines.join("\n") };
}

export function giftCardStatusLabel(status: string): string {
  switch (status) {
    case "ACTIVE": return "Active";
    case "REDEEMED": return "Fully redeemed";
    case "VOID": return "Voided";
    case "EXPIRED": return "Expired";
    default: return status;
  }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth";
import { canAccess } from "@/lib/access";
import { externalUrl } from "@/lib/request-url";
import { allocateUniqueCode, GIFT_CARD_MAX, GIFT_CARD_VALIDITY_DAYS } from "@/lib/gift-cards";

// Admin gift-card management: issue a new card, adjust its balance, or void it.
// Front-desk (STAFF) and above may issue/adjust; INSTRUCTOR is denied via access.
export async function POST(req: Request) {
  const auth = await getSession();
  if (!auth) return NextResponse.redirect(externalUrl(req, "/login"), 303);
  if (!canAccess(auth.role, "/gift-cards")) return NextResponse.redirect(externalUrl(req, "/dashboard"), 303);

  const form = await req.formData();
  const action = String(form.get("action") ?? "");
  const back = (q: string) => NextResponse.redirect(externalUrl(req, `/gift-cards${q}`), 303);

  try {
    if (action === "issue") {
      const amount = Math.round((Number(form.get("amount") ?? 0) || 0) * 100) / 100;
      if (amount <= 0 || amount > GIFT_CARD_MAX) return back("?err=amount");
      const tenant = await db.tenant.findUniqueOrThrow({ where: { id: auth.tenantId } });
      const code = await allocateUniqueCode(db, tenant.id);
      const expiresAt = new Date(Date.now() + GIFT_CARD_VALIDITY_DAYS * 86400_000);
      await db.$transaction(async (tx) => {
        const card = await tx.giftCard.create({
          data: {
            tenantId: tenant.id,
            code,
            initialAmount: amount.toFixed(2),
            balance: amount.toFixed(2),
            currency: tenant.currency,
            purchaserEmail: String(form.get("purchaserEmail") ?? "").trim() || null,
            recipientEmail: String(form.get("recipientEmail") ?? "").trim() || null,
            message: String(form.get("message") ?? "").trim() || null,
            status: "ACTIVE",
            expiresAt,
          },
        });
        await tx.giftCardTxn.create({
          data: { giftCardId: card.id, amount: amount.toFixed(2), type: "PURCHASE", note: "Issued by staff" },
        });
      });
      return back(`?ok=issued&code=${encodeURIComponent(code)}`);
    }

    if (action === "adjust") {
      const id = String(form.get("id") ?? "");
      const delta = Math.round((Number(form.get("delta") ?? 0) || 0) * 100) / 100;
      if (!id || delta === 0) return back("?err=adjust");
      const card = await db.giftCard.findFirst({ where: { id, tenantId: auth.tenantId } });
      if (!card) return back("?err=notfound");
      const balance = Number(card.balance);
      const newBalance = Math.round((balance + delta) * 100) / 100;
      if (newBalance < 0) return back("?err=negative");
      await db.$transaction(async (tx) => {
        await tx.giftCard.update({
          where: { id: card.id },
          data: {
            balance: newBalance.toFixed(2),
            // Re-activate a spent card if credit is added back.
            status: card.status === "REDEEMED" && newBalance > 0 ? "ACTIVE" : card.status,
          },
        });
        await tx.giftCardTxn.create({
          data: { giftCardId: card.id, amount: delta.toFixed(2), type: "ADJUST", note: String(form.get("note") ?? "").trim() || "Manual adjustment" },
        });
      });
      return back("?ok=adjusted");
    }

    if (action === "void") {
      const id = String(form.get("id") ?? "");
      const card = await db.giftCard.findFirst({ where: { id, tenantId: auth.tenantId } });
      if (!card) return back("?err=notfound");
      await db.$transaction(async (tx) => {
        await tx.giftCard.update({ where: { id: card.id }, data: { status: "VOID" } });
        await tx.giftCardTxn.create({ data: { giftCardId: card.id, amount: "0.00", type: "ADJUST", note: "Voided by staff" } });
      });
      return back("?ok=voided");
    }

    return back("?err=action");
  } catch {
    return back("?err=server");
  }
}

import { NextResponse } from "next/server";
import { rateLimit } from "@/lib/rate-limit";
import { tenantBySlugOrDomain } from "@/lib/public-tenant";
import { studioStripe, studioStripeEnabled, toStripeAmount } from "@/lib/stripe";
import { externalUrl } from "@/lib/request-url";
import { GIFT_CARD_MIN, GIFT_CARD_MAX } from "@/lib/gift-cards";

// Customer buys a gift card, charged through the STUDIO's own Stripe (the same
// integration used for online package purchases). The card itself is only
// created after payment is confirmed — see confirm/route.ts. If the studio has
// not connected Stripe, this endpoint cleanly bounces back with ?err=stripe
// (nothing to charge against — no keys are invented).
export async function POST(req: Request) {
  if (!rateLimit(req, "gc-checkout", 8, 60)) return new NextResponse("Slow down.", { status: 429 });

  const form = await req.formData();
  const slug = String(form.get("slug") ?? "");
  const back = `/book/${slug}/gift-cards`;

  const tenant = await tenantBySlugOrDomain(slug);
  if (!tenant || tenant.status === "SUSPENDED") return NextResponse.redirect(externalUrl(req, "/login"), 303);

  const stripe = studioStripe(tenant);
  if (!stripe || !studioStripeEnabled(tenant)) {
    return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);
  }

  const amount = Math.round((Number(form.get("amount") ?? 0) || 0) * 100) / 100;
  const recipientEmail = String(form.get("recipientEmail") ?? "").trim().slice(0, 200);
  const purchaserEmail = String(form.get("purchaserEmail") ?? "").trim().slice(0, 200);
  const message = String(form.get("message") ?? "").trim().slice(0, 500);
  if (amount < GIFT_CARD_MIN || amount > GIFT_CARD_MAX) {
    return NextResponse.redirect(externalUrl(req, `${back}?err=amount`), 303);
  }
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(recipientEmail)) {
    return NextResponse.redirect(externalUrl(req, `${back}?err=email`), 303);
  }

  try {
    const origin = externalUrl(req, "").toString().replace(/\/$/, "");
    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      line_items: [{
        quantity: 1,
        price_data: {
          currency: tenant.currency.toLowerCase(),
          unit_amount: toStripeAmount(amount, tenant.currency),
          product_data: {
            name: `Gift card — ${tenant.name}`,
            description: `A ${tenant.currency} ${amount.toFixed(2)} gift card${recipientEmail ? ` for ${recipientEmail}` : ""}`,
          },
        },
      }],
      customer_email: purchaserEmail || undefined,
      // Metadata is echoed back on the success redirect where the card is minted.
      metadata: {
        kind: "giftcard",
        tenantId: tenant.id,
        amount: amount.toFixed(2),
        recipientEmail,
        purchaserEmail,
        message,
      },
      success_url: `${origin}/api/public/gift-cards/confirm?slug=${encodeURIComponent(slug)}&sid={CHECKOUT_SESSION_ID}`,
      cancel_url: `${origin}${back}?err=cancelled`,
    });
    return NextResponse.redirect(session.url!, 303);
  } catch {
    return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);
  }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { tenantBySlugOrDomain } from "@/lib/public-tenant";
import { studioStripe } from "@/lib/stripe";
import { moneyFormatter } from "@/lib/tenant";
import { sendEmail } from "@/lib/mailer";
import { externalUrl } from "@/lib/request-url";
import { allocateUniqueCode, purchaseEmailBody, GIFT_CARD_VALIDITY_DAYS } from "@/lib/gift-cards";

// Stripe Checkout success landing for a gift-card purchase. Mirrors the package
// confirm flow: verify the session server-side (no webhook needed for
// studio-level payments), then mint the card exactly once. Idempotency is
// enforced by the unique GiftCard.stripeSessionId — a refresh/retry of this URL
// finds the existing card instead of creating a duplicate.
export async function GET(req: Request) {
  const url = new URL(req.url);
  const slug = url.searchParams.get("slug") ?? "";
  const sid = url.searchParams.get("sid") ?? "";
  const back = `/book/${slug}/gift-cards`;

  const tenant = await tenantBySlugOrDomain(slug);
  const stripe = tenant ? studioStripe(tenant) : null;
  if (!tenant || !stripe || !sid) return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);

  try {
    const session = await stripe.checkout.sessions.retrieve(sid);
    if (session.payment_status !== "paid" || session.metadata?.tenantId !== tenant.id || session.metadata?.kind !== "giftcard") {
      return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);
    }

    let card = await db.giftCard.findUnique({ where: { stripeSessionId: sid } });
    if (!card) {
      const amount = Math.round((Number(session.metadata.amount ?? 0) || 0) * 100) / 100;
      const recipientEmail = (session.metadata.recipientEmail || "").trim() || null;
      const purchaserEmail = (session.metadata.purchaserEmail || session.customer_details?.email || "").trim() || null;
      const message = (session.metadata.message || "").trim() || null;
      const code = await allocateUniqueCode(db, tenant.id);
      const expiresAt = new Date(Date.now() + GIFT_CARD_VALIDITY_DAYS * 86400_000);
      card = await db.$transaction(async (tx) => {
        const created = await tx.giftCard.create({
          data: {
            tenantId: tenant.id,
            code,
            initialAmount: amount.toFixed(2),
            balance: amount.toFixed(2),
            currency: tenant.currency,
            purchaserEmail,
            recipientEmail,
            message,
            status: "ACTIVE",
            expiresAt,
            stripeSessionId: sid,
          },
        });
        await tx.giftCardTxn.create({
          data: { giftCardId: created.id, amount: amount.toFixed(2), type: "PURCHASE", note: "Online purchase" },
        });
        return created;
      });

      // Email the recipient (falls back to the purchaser). Non-fatal on failure —
      // the card exists regardless and is viewable via the link.
      const to = card.recipientEmail || card.purchaserEmail;
      if (to) {
        const fmt = moneyFormatter(tenant.currency);
        const viewUrl = externalUrl(req, `/book/${slug}/gift-cards/${encodeURIComponent(card.code)}`).toString();
        const { subject, body } = purchaseEmailBody({
          studio: tenant.name,
          amount: fmt.format(Number(card.initialAmount)),
          code: card.code,
          message: card.message,
          viewUrl,
        });
        await sendEmail({ tenantId: tenant.id, to, subject, body }).catch(() => {});
      }
    }

    return NextResponse.redirect(externalUrl(req, `/book/${slug}/gift-cards/${encodeURIComponent(card.code)}?ok=purchased`), 303);
  } catch {
    return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);
  }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { rateLimit } from "@/lib/rate-limit";
import { tenantBySlugOrDomain } from "@/lib/public-tenant";
import { moneyFormatter } from "@/lib/tenant";
import { normaliseCode, giftCardStatusLabel } from "@/lib/gift-cards";

// Public "check my gift-card balance" lookup, scoped to one tenant. Rate-limited
// and returns only non-sensitive fields (never purchaser/recipient email).
export async function POST(req: Request) {
  if (!rateLimit(req, "gc-balance", 15, 60)) return NextResponse.json({ error: "slow_down" }, { status: 429 });

  let body: { slug?: string; code?: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "bad_json" }, { status: 400 });
  }
  const tenant = await tenantBySlugOrDomain(String(body.slug ?? ""));
  if (!tenant) return NextResponse.json({ error: "not_found" }, { status: 404 });

  const code = normaliseCode(String(body.code ?? ""));
  if (!code) return NextResponse.json({ error: "no_code" }, { status: 400 });

  const card = await db.giftCard.findFirst({
    where: { tenantId: tenant.id, code },
    select: { balance: true, initialAmount: true, currency: true, status: true, expiresAt: true },
  });
  if (!card) return NextResponse.json({ found: false });

  const fmt = moneyFormatter(card.currency);
  const expired = !!card.expiresAt && card.expiresAt.getTime() < Date.now();
  return NextResponse.json({
    found: true,
    status: expired && card.status === "ACTIVE" ? "EXPIRED" : card.status,
    statusLabel: expired && card.status === "ACTIVE" ? "Expired" : giftCardStatusLabel(card.status),
    balance: Number(card.balance),
    balanceLabel: fmt.format(Number(card.balance)),
    initialLabel: fmt.format(Number(card.initialAmount)),
    expiresAt: card.expiresAt,
  });
}

