cd /opt/nxeon
cat > ./_board.mjs <<'EOF'
import fs from 'node:fs';
import { PrismaClient } from '@prisma/client';
for(const line of fs.readFileSync('/opt/nxeon/.env','utf8').split('\n')){
  const m=line.match(/^([A-Z0-9_]+)=(.*)$/); if(m){let v=m[2].trim(); if((v.startsWith('"')&&v.endsWith('"'))||(v.startsWith("'")&&v.endsWith("'")))v=v.slice(1,-1); if(!process.env[m[1]])process.env[m[1]]=v;}
}
const db = new PrismaClient();
const CARD='cmsbkj4gg0025hlv5rsobgtgx', COL='cmsbk8miq0017hlv5elhzx9vf';
const card = await db.card.findUnique({ where:{ id: CARD }});
if(!card){ console.error('CARD NOT FOUND'); process.exit(2); }
const col = await db.boardColumn.findUnique({ where:{ id: COL }});
console.error('card:', card.title, '| current col:', card.columnId, '| target col:', col?.name ?? '??');
const top = await db.card.findFirst({ where:{ columnId: COL }, orderBy:{ position:'desc' }, select:{ position:true }});
const pos = (top?.position ?? 0) + 1;
await db.card.update({ where:{ id: CARD }, data:{ columnId: COL, position: pos, assignee: card.assignee || 'claude' }});
const body = [
'Built the Gift Cards feature on an isolated worktree — branch pushed, not merged/deployed.',
'',
'Branch: feature/gift-cards (origin) · worktree /opt/nexis-wt-giftcard on .215 (built from origin/main HEAD 6cfc970).',
'',
'What shipped:',
'- Prisma (additive): GiftCard (balance = source of truth) + GiftCardTxn ledger (PURCHASE|REDEEM|ADJUST), enums GiftCardStatus/GiftCardTxnType, Tenant.giftCards relation. Code unique per-tenant so cards never cross tenants.',
'- Purchase (customer): /book/[slug]/gift-cards buy page -> Stripe Checkout via the existing studio Stripe integration -> confirm route mints the card server-side (idempotent on unique stripeSessionId) + emails the recipient (nodemailer, existing mailer). Printable card view /book/[slug]/gift-cards/[code] with an inline server-generated QR (no runtime network).',
'- Redemption: atomic guarded decrement (updateMany WHERE balance>=amount inside the checkout $transaction) prevents double-spend/races and negative balances; partial redemption supported; every draw logged as a REDEEM txn. Wired into POS /api/checkout (new giftCardCode field).',
'- Admin: /gift-cards page — list, search, balance + full ledger, issue/adjust/void. Nav links added (sidebar + customer nav); INSTRUCTOR role denied.',
'- tsc --noEmit clean; npm run build passes.',
'',
'Stripe config the user must supply: none new — reuses each studio\'s own pasted key (policies.stripe). Online purchase self-gates off when a studio has no key (front desk can still issue cards). No webhook needed (studio payments verified on the success redirect, same as packages).',
'',
'Deploy steps (user):',
'1) On .215: cd /opt/nexis, git fetch, merge/checkout feature/gift-cards.',
'2) npx prisma db push  (targets nexis_staging — additive, no data loss).',
'3) npx prisma generate && npm run build && restart the app service.',
].join('\n');
await db.cardComment.create({ data:{ cardId: CARD, authorName: 'Claude', body }});
console.error('MOVED + COMMENTED. new position', pos);
await db.$disconnect();
EOF
